def count_camels(n, t):
    # dp[pos][prev_y][curr_y][peaks][valleys][trend]
    # trend: 0 = decreasing, 1 = increasing
    dp = [[[[[0]*2 for _ in range(t)] for _ in range(t+1)] for _ in range(5)] for _ in range(5)]

    # Initialize for first two points
    for y1 in range(1, 5):
        for y2 in range(1, 5):
            if y1 == y2:
                continue
            trend = 1 if y2 > y1 else 0
            dp[y1][y2][0][0][trend] += 1

    for pos in range(3, n+1):
        new_dp = [[[[[0]*2 for _ in range(t)] for _ in range(t+1)] for _ in range(5)] for _ in range(5)]
        for y_prevprev in range(1, 5):
            for y_prev in range(1, 5):
                for peaks in range(t+1):
                    for valleys in range(t):
                        for trend in range(2):
                            ways = dp[y_prevprev][y_prev][peaks][valleys][trend]
                            if ways == 0:
                                continue
                            for y in range(1, 5):
                                if y == y_prev:
                                    continue
                                new_trend = 1 if y > y_prev else 0
                                new_peaks = peaks
                                new_valleys = valleys
                                if new_trend != trend:
                                    if trend == 1 and new_trend == 0:
                                        new_peaks += 1
                                    elif trend == 0 and new_trend == 1:
                                        new_valleys += 1
                                if new_peaks > t or new_valleys > t-1:
                                    continue
                                new_dp[y_prev][y][new_peaks][new_valleys][new_trend] += ways
        dp = new_dp

    total = 0
    for y_prevprev in range(1, 5):
        for y_prev in range(1, 5):
