import sys
from functools import lru_cache

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, t = map(int, data)

    @lru_cache(maxsize=None)
    def dp(pos, last_y, trend, peaks, valleys):
        # pos: current position (1-based), last_y: y at pos-1
        # trend: -1 down, 0 flat (not used), 1 up, 2 start (no trend yet)
        if pos > n:
            # finished sequence, count peaks and valleys
            return 1 if peaks == t and valleys == t - 1 else 0

        total = 0
        for y in range(1, 5):
            if y == last_y:
                continue  # no horizontal segments

            if trend == 2:  # starting, no previous trend
                new_trend = 1 if y > last_y else -1
                total += dp(pos + 1, y, new_trend, peaks, valleys)
            else:
                if y > last_y:
                    new_trend = 1
                    # valley if previous trend was down
                    if trend == -1:
                        total += dp(pos + 1, y, new_trend, peaks, valleys + 1)
                    else:
                        total += dp(pos + 1, y, new_trend, peaks, valleys)
                else:  # y < last_y
                    new_trend = -1
                    # peak if previous trend was up
                    if trend == 1:
                        total += dp(pos + 1, y, new_trend, peaks + 1, valleys)
                    else:
                        total += dp(pos + 1, y, new_trend, peaks, valleys)
        return total

    ans = 0
    # choose starting y1
    for y1 in range(1, 5):
        ans += dp(2, y1, 2, 0, 0)

    print(ans)

if __name__ == "__main__":
    main()
